use verus::prelude::*;

verus! {

    /// Given a non‐empty Vec of Vec<i32>, returns the minimum length
    /// of any inner Vec.  Inner Vecs may be empty.
    pub fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize
        requires
            // Outer list must be non‐empty
            list.len() > 0,
        ensures
            // The result is at most the length of every inner list
            forall |i: usize| i < list.len() ==> result <= list[i].len(),
        ensures
            // There is at least one inner list whose length equals result
            exists |i: usize| i < list.len() && list[i].len() == result,
    {
        // Initialize min to the length of the first inner list
        let mut min = list[0].len();
        // Start scanning from the second inner list
        let mut i: usize = 1;

        // Loop until we've processed all inner lists
        while i < list.len()
            invariant
                // i always stays within [1, list.len()]
                1 <= i && i <= list.len(),
            invariant
                // For all already‐seen indices j < i, min <= list[j].len()
                forall |j: usize| j < i ==> min <= list[j].len(),
            invariant
                // There is at least one j < i with list[j].len() == min
                exists |j: usize| j < i && list[j].len() == min,
            decreases
                // We make progress because (list.len() - i) strictly decreases
                list.len() - i,
        {
            let len_i = list[i].len();
            if len_i < min {
                min = len_i;
            }
            i += 1;
        }

        // At this point i == list.len(), so the invariants give exactly
        // the two post‐conditions we wanted.
        min
    }

}